-- Baseline: framework objects only. Domain tables come in later migrations.
--
-- Conventions for every migration in this directory:
--
-- * Forward-only. A migration that has been applied anywhere is never edited,
--   renamed or removed (the runner refuses a changed checksum); fix forward
--   with a new file. Versions are contiguous: NNNN_description.sql.
-- * Each file runs in one transaction; never use `-- no-transaction`.
-- * Object IDs are opaque text generated by the service, never chosen by the
--   caller; their format belongs to the ID-generation work, not to SQL
--   defaults.
-- * Tenant-scoped rows carry tenant_id with a foreign key to the tenant.
--   Foreign keys never use ON DELETE CASCADE across authority boundaries;
--   records are soft-disabled through a status column instead.
-- * Timestamps are timestamptz; revisions are bigint and only increase.
-- * Immutable or append-only tables attach skyoauth_reject_mutation() below.

-- Rejects UPDATE, DELETE and TRUNCATE on the table it is attached to.
-- Attach with:
--   CREATE TRIGGER <table>_append_only
--       BEFORE UPDATE OR DELETE ON <table>
--       FOR EACH ROW EXECUTE FUNCTION skyoauth_reject_mutation();
--   CREATE TRIGGER <table>_no_truncate
--       BEFORE TRUNCATE ON <table>
--       FOR EACH STATEMENT EXECUTE FUNCTION skyoauth_reject_mutation();
CREATE FUNCTION skyoauth_reject_mutation() RETURNS trigger
    LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION '% on append-only table % is not allowed', TG_OP, TG_TABLE_NAME
        USING ERRCODE = 'restrict_violation';
END;
$$;

-- Identifies the database as a skyoauth schema. Exactly one immutable row.
CREATE TABLE schema_info (
    singleton   boolean     PRIMARY KEY DEFAULT true CHECK (singleton),
    product     text        NOT NULL CHECK (product = 'skyoauth'),
    created_at  timestamptz NOT NULL DEFAULT now()
);

INSERT INTO schema_info (product) VALUES ('skyoauth');

CREATE TRIGGER schema_info_append_only
    BEFORE UPDATE OR DELETE ON schema_info
    FOR EACH ROW EXECUTE FUNCTION skyoauth_reject_mutation();

CREATE TRIGGER schema_info_no_truncate
    BEFORE TRUNCATE ON schema_info
    FOR EACH STATEMENT EXECUTE FUNCTION skyoauth_reject_mutation();
